 const runAI=async(operation:string,rewriteField?:string)=>{if(!project||!await flushSave())return;setAiTool(operation==="job-match"||operation==="tailor"?"match":operation==="summary"?"summary":operation==="review"?"review":"hub");aiRetryRef.current={operation,field:rewriteField};setBusy(true);setError("");setNotice("");setToolResult(null);try{let path=`${ROOT}/resumes/${encodeURIComponent(project.id)}/ai/${operation}`,options:RequestInit&{timeoutMs?:number}={...json({}),timeoutMs:RESUME_AI_TIMEOUT_MS};if(operation==="job-match"||operation==="tailor"){const query=new URLSearchParams({job_description:jobDescription});path+=`?${query.toString()}`}if(operation==="rewrite"){const matching=project.document.sections.flatMap(section=>section.entries.map(entry=>({section,entry}))).find(({section,entry})=>rewriteField?`${entry.id}:body_html`===rewriteField:section.kind==="summary");const entry=matching?.entry;if(!entry){setError("Add resume content before asking AI to rewrite it.");return}options={...json({field:rewriteField||`${entry.id}:body_html`,text:entry.body_html,mode:"improve"}),timeoutMs:RESUME_AI_TIMEOUT_MS}}const result=await api<any>(path,options);if(projectRef.current?.id!==project.id)return;setToolResult(result);aiRetryRef.current=null;if(result.proposal_id||result.id&&result.changes){setProposal(result as Proposal);setTab("ai");setProposals(v=>[result as Proposal,...v.filter(x=>x.id!==result.id)]);setNotice(`${(aiLabels[operation]||operation)} proposal is ready. Review it before applying.`)}else{setProposal(null);setNotice(result.note||`${(aiLabels[operation]||operation)} results are ready.`);if(operation==="skills")setProposal({id:"skills",operation:"skills",status:"results",source_revision:project.revision,proposal:result})}}catch(e){setError((e as Error).message)}finally{setBusy(false)}};
 const addConfirmedSkills=async(skillsToAdd:string[])=>{if(!project||!skillsToAdd.length||!await flushSave())return;const current=projectRef.current;if(!current)return;setBusy(true);setError("");try{const result=await api<any>(`${ROOT}/resumes/${encodeURIComponent(project.id)}/ai/add-skills`,{...json({skills:skillsToAdd,expected_revision:current.revision})});if(!acceptAIResume(current))return;projectRef.current=result.resume;persistedSnapshotRef.current=projectSnapshot(result.resume);setProject(result.resume);setSaveState("saved");setSelectedSkills([]);setPreviewKey(v=>v+1);setNotice(result.added.length?`Added ${result.added.join(", ")} as revision ${result.revision}.`:"Those skills were already present.");await refreshList()}catch(e){if(e instanceof ApiError&&e.status===409)setConflict(true);setError((e as Error).message)}finally{setBusy(false)}};
