 const decideProposal=async(item:Proposal,decision:"accept"|"reject"|"apply")=>{if(!project||!await flushSave())return;const current=projectRef.current;if(!current)return;const id=item.id||item.proposal_id;if(!id)return;setBusy(true);setError("");try{if(decision==="reject"){await api(`${ROOT}/proposals/${encodeURIComponent(id)}/reject`,{...json({})});setProposal(null);await loadProposals();setNotice("Proposal rejected. Resume content was not changed.");return}if(decision==="accept"){const accepted=await api<any>(`${ROOT}/proposals/${encodeURIComponent(id)}/accept`,{...json({})});setProposal(accepted);await loadProposals();setNotice("Proposal accepted. Apply it when you are ready.");return}const changes=(item.proposal?.changes||item.changes||[]) as Array<any>;const applied=await api<any>(`${ROOT}/proposals/${encodeURIComponent(id)}/apply`,{...json({expected_revision:current.revision,accepted_ids:changes.map(x=>x.id)})});if(!acceptAIResume(current))return;projectRef.current=applied.resume;persistedSnapshotRef.current=projectSnapshot(applied.resume);setProject(applied.resume);setSaveState("saved");setPreviewKey(v=>v+1);setProposal(null);setNotice("Accepted changes applied as a new revision.");await Promise.all([refreshList(),loadProposals()])}catch(e){if(e instanceof ApiError&&e.status===409){setConflict(true);setSaveState("conflict")}setError((e as Error).message)}finally{setBusy(false)}};
 const startConversation=async(id=project?.id,restart=false)=>{if(!id)return;if(project?.id===id&&!await flushSave())return;setBusy(true);setError("");try{const row=await api<any>(`${ROOT}/resumes/${encodeURIComponent(id)}/interviews`,{...json({restart}),timeoutMs:RESUME_AI_TIMEOUT_MS});if(projectRef.current?.id!==id)return;setConversation(row);setTab("ai");setAiTool("chat");setMobileView("editor");if(row.document&&projectRef.current){const current=projectRef.current,updated={...current,document:row.document,revision:row.resume_revision??current.revision};projectRef.current=updated;persistedSnapshotRef.current=projectSnapshot(updated);setProject(updated);setSaveState("saved");setProjects(rows=>rows.map(item=>item.id===updated.id?{...item,...updated}:item));setPreviewKey(value=>value+1)}}catch(e){setError((e as Error).message)}finally{setBusy(false)}};
