 const endConversation=async()=>{if(!conversation)return;setBusy(true);setError("");try{await request(`${ROOT}/interviews/${encodeURIComponent(conversation.id)}`,{method:"DELETE"});setConversation(null);setEditingAnswer(null);setNotice("Conversation ended. Resume facts and revisions remain saved.")}catch(e){setError((e as Error).message)}finally{setBusy(false)}};
 const acceptAIResume=(current:Project)=>{const active=projectRef.current;if(active?.id!==current.id)return false;if(projectSnapshot(active)!==projectSnapshot(current)){setConflict(true);setSaveState("conflict");setError("Your resume changed while AI was processing. Reload the saved version before continuing.");return false}return true};
