 const editAnswer=async(index:number)=>{if(!conversation||!project||!editText.trim())return;if(!await flushSave())return;const current=projectRef.current;if(!current)return;setBusy(true);setError("");try{const row=await api<any>(`${ROOT}/interviews/${encodeURIComponent(conversation.id)}/messages/${index}/edit`,{...json({message:editText,expected_revision:current.revision}),timeoutMs:RESUME_AI_TIMEOUT_MS});if(!acceptAIResume(current))return;setConversation(row);setEditingAnswer(null);if(row.document){const updated={...current,document:row.document,revision:row.resume_revision??current.revision};projectRef.current=updated;persistedSnapshotRef.current=projectSnapshot(updated);setProject(updated);setProjects(rows=>rows.map(item=>item.id===updated.id?{...item,...updated}:item));setSaveState("saved")}setPreviewKey(v=>v+1)}catch(e){if(e instanceof ApiError&&e.status===409){setConflict(true);setSaveState("conflict")}setError((e as Error).message)}finally{setBusy(false)}};
 useEffect(()=>{if(tab==="ai"&&project){void loadProposals()}},[tab,project?.id]);
 const previewInput=useMemo(()=>project?JSON.stringify({title:project.title.trim()||"Untitled Resume",document:project.document,presentation:project.presentation}):"",[project?.title,project?.document,project?.presentation]);useEffect(()=>{setPreviewPages(1);setPreviewHeight(paperSize(project?.presentation?.paper_size).height);if(!project||!previewInput){setPreviewHtml("");setPreviewLoading(false);setPreviewError("");return}const controller=new AbortController();setPreviewLoading(true);setPreviewError("");const timer=window.setTimeout(()=>{request(`${ROOT}/resumes/${encodeURIComponent(project.id)}/preview`,{...json(JSON.parse(previewInput)),signal:controller.signal,timeoutMs:RESUME_AI_TIMEOUT_MS}).then(response=>response.text()).then(html=>{if(!controller.signal.aborted)setPreviewHtml(html)}).catch(error=>{if(!controller.signal.aborted)setPreviewError((error as Error).message)}).finally(()=>{if(!controller.signal.aborted)setPreviewLoading(false)})},180);return()=>{window.clearTimeout(timer);controller.abort()}},[project?.id,previewInput,previewKey]);
 const addSection=(kind:string)=>{const meta=sections.find(s=>s.kind===kind);if(!meta||!project)return;const section:Section={id:newId(),kind,name:meta.name,hidden:false,column:["skills","certifications","languages"].includes(kind)?"aside":"main",variant:kind==="skills"?"inline":"list",page_break_before:false,entries:kind==="summary"?[newEntry()]:[]};updateDoc(doc=>({...doc,sections:[...doc.sections,section]}))};
